import { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { registerCompany } from "../Features/CompanySlice";
import { Link, useNavigate } from "react-router-dom";
import "../Styles/CompanyRegister.css";
import companyImg from "../Images/company-man.png";

import { companySchemaValidation } from "../Validations/CompanyValidation";
import * as yup from "yup";
import { useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";

const INDUSTRIES = [
  "",
  "Technology",
  "Hospitality / Coffee Shops",
  "Retail / Store",
  "Education",
  "Logistics",
  "Government",
  "Other",
];

const LOCATIONS = ["", "Salalah", "Taqah", "Mirbat", "Mughsail", "Other"];

const CompanyRegister = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { isLoading, isError, isSuccess } = useSelector(
    (state) => state.company
  );

  const [companyName, setCompanyName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [industry, setIndustry] = useState("");
  const [location, setLocation] = useState("");
  const [foundedDate, setFoundedDate] = useState("");

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm({
    resolver: yupResolver(companySchemaValidation),
  });

  const onSubmit = (data) => {
    try {
      const companyData = {
        companyName: data.companyName,
        email: data.email,
        password: data.password,
        industry: data.industry,
        location: data.location,
        foundedDate: data.foundedDate,
      };
      dispatch(registerCompany(companyData));
      alert("Validation successful! Company registered.");
      navigate("/company-profile");
    } catch (error) {
      console.log("Error:", error);
      alert("Registration failed. Try again.");
    }
  };

  useEffect(() => {
    if (isSuccess) {
      alert("Company Registered");
      navigate("/company-profile");
    } else if (isError) {
      alert("Registration failed. Try again.");
    }
  }, [isSuccess, isError, navigate]);

  return (
    <div className="company-container">
      <div className="company-box">
        <div className="company-card">
          <h1 className="company-title">
            Create your <span className="accent">account</span>
          </h1>
          <p className="company-sub">Please fill in your company details</p>

          <div className="role-switch">
            <Link to="/user-register" className="role-btn">
              Student
            </Link>
            <Link to="/company-register" className="role-btn active">
              Company
            </Link>
          </div>

          <form onSubmit={handleSubmit(onSubmit)}>
            <label>Company Name</label>
            <input
              type="text"
              placeholder="Dhofar Advertising Co."
              {...register("companyName", {
                value: companyName,
                onChange: (e) => setCompanyName(e.target.value),
              })}
            />
            <p className="error">{errors.companyName?.message}</p>

            <div className="row-flex">
              <div className="col-half">
                <label>Email</label>
                <input
                  type="email"
                  placeholder="hr@company.com"
                  {...register("email", {
                    value: email,
                    onChange: (e) => setEmail(e.target.value),
                  })}
                />
                <p className="error">{errors.email?.message}</p>
              </div>

              <div className="col-half">
                <label>Password</label>
                <input
                  type="password"
                  placeholder="********"
                  {...register("password", {
                    value: password,
                    onChange: (e) => setPassword(e.target.value),
                  })}
                />
                <p className="error">{errors.password?.message}</p>
              </div>
            </div>

            <div className="row-flex">
              <div className="col-half">
                <label>Industry Type</label>
                <select
                  {...register("industry", {
                    value: industry,
                    onChange: (e) => setIndustry(e.target.value),
                  })}
                >
                  {INDUSTRIES.map((i, idx) => (
                    <option key={idx} value={i}>
                      {i === "" ? "Select your industry" : i}
                    </option>
                  ))}
                </select>
                <p className="error">{errors.industry?.message}</p>
              </div>

              <div className="col-half">
                <label>Location</label>
                <select
                  {...register("location", {
                    value: location,
                    onChange: (e) => setLocation(e.target.value),
                  })}
                >
                  {LOCATIONS.map((l, idx) => (
                    <option key={idx} value={l}>
                      {l === "" ? "Select your location" : l}
                    </option>
                  ))}
                </select>
                <p className="error">{errors.location?.message}</p>
              </div>
            </div>

            <label>Founded Date</label>
            <input
              type="date"
              {...register("foundedDate", {
                value: foundedDate,
                onChange: (e) => setFoundedDate(e.target.value),
              })}
            />
            <p className="error">{errors.foundedDate?.message}</p>

            <button type="submit" className="company-btn" disabled={isLoading}>
              {isLoading ? "Registering..." : "Sign up"}
            </button>

            <p className="login-text">
              Already have an account?{" "}
              <Link to="/login" className="login-link">
                Log in now!
              </Link>
            </p>
          </form>
        </div>

        <div className="company-image">
          <img src={companyImg} alt="Company registration" />
        </div>
      </div>
    </div>
  );
};

export default CompanyRegister;
